<script lang="ts">
 import {onMount} from 'svelte';
 import {enhance} from '$app/forms';
 import {Wallet,ArrowDownLeft,ArrowUpRight,ChartNoAxesCombined,BookOpen,Landmark,CheckCheck,Sparkles} from 'lucide-svelte';
 import {money,categories,type FinanceWorkspace} from '$lib/finance';
 let {data,form}:{data:{workspace:FinanceWorkspace;basePath:string};form?:{message?:string;failed?:boolean}|null}=$props();
 const w=$derived(data.workspace),s=$derived(w.state),r=$derived(w.reports);
 let ready=$state(false);onMount(()=>ready=true);
 let view=$state('home'),arFilter=$state('attention'),apFilter=$state('review'),accountFilter=$state(''),lineCount=$state(1);
 const today=new Date().toISOString().slice(0,10);
 const jobName=(id:string)=>w.jobChoices.find(j=>j.id===id)?.name||id;
 const vendorName=(id:string)=>w.vendors.find(v=>v.id===id)?.name||id;
 const tabs=[['home','Overview',Wallet],['ar','Money in',ArrowDownLeft],['ap','Money out',ArrowUpRight],['jobs','Job health',ChartNoAxesCombined],['cash','Bank & reconciliation',Landmark],['reports','Statements',BookOpen],['ledger','Accounting',BookOpen],['close','Close',CheckCheck]] as const;
 const arItems=$derived(r.aging.filter(i=>i.kind==='AR'&&(arFilter==='all'||arFilter==='attention'&&i.daysPastDue>0&&i.balance>0||arFilter==='upcoming'&&i.daysPastDue===0&&i.balance>0||arFilter==='paid'&&i.balance===0)));
 const apItems=$derived(s.bills.filter(b=>apFilter==='all'||apFilter==='review'&&b.status==='PENDING_APPROVAL'||apFilter==='exceptions'&&b.matchExceptions.length>0||apFilter==='due'&&b.journalId&&b.dueDate>=r.asOf||apFilter==='overdue'&&b.journalId&&b.dueDate<r.asOf));
</script>
<svelte:head><title>Finance · TurnKeyOps</title></svelte:head>
<div class="finance">
 <header><div><p class="eyebrow">FINANCE</p><h1>Keep money moving.</h1><p>Cash, obligations and Job performance from recorded transactions.</p></div><form method="GET" class="report-dates"><label>From<input type="date" name="from" value={r.from}/></label><label>As of<input type="date" name="asOf" value={r.asOf}/></label><button>Update dates</button></form></header>
 {#if form?.message}<p role={form.failed?'alert':'status'} class:problem={form.failed} class="feedback">{form.message}</p>{/if}
 <nav aria-label="Finance views">{#each tabs as [key,label,Icon]}<button type="button" disabled={!ready} aria-current={view===key?'page':undefined} onclick={()=>view=key}><Icon size={16} aria-hidden="true"/>{label}</button>{/each}</nav>
 {#if s.accounts.length===0}
  <section><h2>Set up your financial core</h2><p>Start with contractor accounts, then add monthly periods and reconcile opening balances before importing activity.</p>{#if w.canControl}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={s.version}/><button class="primary" name="action" value="initialize">Create contractor defaults</button></form>{:else}<p>A Finance owner can complete setup.</p>{/if}</section>
 {:else if view==='home'}
  <div class="summary">{#each [['Cash',r.cash.reduce((sum,c)=>sum+c.balance,0),'Posted cash position'],['Money in',r.ar,'Customer balances'],['Money out',r.ap,'Vendor obligations'],['Profit',r.profit,'For the selected dates']] as [label,value,note]}<section><h2>{label}</h2><strong>{money(Number(value))}</strong><p>{note}</p></section>{/each}</div>
  <section><div class="section-heading"><h2>Needs your attention</h2>{#if w.canWrite}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={s.version}/><button name="action" value="bob"><Sparkles size={16} aria-hidden="true"/>Bob’s financial review</button></form>{/if}</div>
   <ul class="priorities"><li><button disabled={!ready} onclick={()=>view='ar'}>{r.aging.filter(i=>i.kind==='AR'&&i.balance>0&&i.daysPastDue>0).length} overdue customer invoices <span>Review money in →</span></button></li><li><button disabled={!ready} onclick={()=>view='ap'}>{s.bills.filter(b=>b.status==='PENDING_APPROVAL').length} bills need approval <span>Review money out →</span></button></li><li><button disabled={!ready} onclick={()=>view='cash'}>{s.bankTransactions.filter(b=>!b.journalId).length} unmatched bank transactions <span>Review bank activity →</span></button></li><li><button disabled={!ready} onclick={()=>view='jobs'}>{w.jobs.filter(j=>j.costDataIncomplete).length} Jobs have incomplete cost data <span>Review Job health →</span></button></li></ul>
  </section>
  <section><h2>Invoice posting</h2><p>Reconcile sent invoices and successful payment/refund events after activity changes. Create all required periods first. Closed periods require an authorized correction.</p>{#if w.canWrite}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={s.version}/><button class="primary" name="action" value="sync-invoices">Reconcile invoice activity</button></form>{/if}<p class="muted">Finance is current through the last successful reconciliation. Existing invoice payment workflows remain available.</p></section>
 {:else if view==='ar'}
  <section><h2>Money in</h2><div class="filters" role="group" aria-label="Invoice filter">{#each [['attention','Needs attention'],['upcoming','Upcoming'],['paid','Paid'],['all','All invoices']] as [key,label]}<button aria-pressed={arFilter===key} onclick={()=>arFilter=key}>{label}</button>{/each}</div>

<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>Customer invoice balances as of {r.asOf}</caption><thead><tr><th scope="col">Invoice</th><th scope="col">Job</th><th scope="col">Due</th><th scope="col">Aging</th><th scope="col" class="number">Balance</th></tr></thead><tbody>{#each arItems as i}<tr><th scope="row"><a href={`${data.basePath}/invoices`}>{i.number}</a><small>{i.id}</small></th><td>{i.jobId?jobName(i.jobId):'—'}</td><td>{i.dueDate}</td><td>{i.balance===0?'Paid':i.bucket}</td><td class="number">{money(i.balance)}</td></tr>{:else}<tr><td colspan="5">No invoices in this view.</td></tr>{/each}</tbody></table></div>
   <p>AR control difference: <strong>{money(r.arDifference)}</strong></p>
  </section>
  {#if w.canWrite}<section><h2>Record a receipt or customer adjustment</h2><p>Allocate one transaction across one or more customer invoices. Record existing provider activity through invoice reconciliation to avoid duplicate receipts.</p><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Transaction<select name="action"><option value="payment">Customer receipt</option><option value="refund">Refund of a recorded receipt</option><option value="credit">Credit memo (original revenue / tax coding)</option></select></label><label>Customer ID<input name="partyId" required/></label><label>Date<input type="date" name="date" value={today} required/></label><label>Amount<input type="number" name="amount" min="0.01" step="0.01" required/></label><label>Cash account<select name="account">{#each s.cashAccounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>Method<input name="method" required/></label><label>External reference<input name="reference" required/></label><label>Unique receipt / credit reference<input name="sourceKey" required/></label><label class="wide">Allocations (invoice ID, amount — one per row)<textarea name="allocations" rows="3" required></textarea></label><label class="wide">Reason<input name="reason" required/></label><button class="primary">Record customer transaction</button></form></section>{/if}
 {:else if view==='ap'}
  <section><h2>Money out</h2><div class="filters" role="group" aria-label="Bill filter">{#each [['review','Needs approval'],['due','Due soon'],['overdue','Overdue'],['exceptions','Match exceptions'],['all','All bills']] as [key,label]}<button aria-pressed={apFilter===key} onclick={()=>apFilter=key}>{label}</button>{/each}</div>

<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>Vendor bills and approval exceptions</caption><thead><tr><th scope="col">Bill</th><th scope="col">Vendor</th><th scope="col">Due</th><th scope="col">Status</th><th scope="col" class="number">Total / Balance</th><th scope="col">Review</th></tr></thead><tbody>{#each apItems as b}<tr><th scope="row">{b.number}<small>{b.id}</small></th><td>{vendorName(b.vendorId)}</td><td>{b.dueDate}</td><td>{b.journalId?(r.aging.find(i=>i.id===b.id)?.balance===0?'PAID':'POSTED'):b.status}</td><td class="number">{money(b.total)} / {b.journalId?money(r.aging.find(i=>i.id===b.id)?.balance):'Unposted'}</td><td>{#each b.matchExceptions as issue}<p class="exception">{issue}</p>{/each}{#if w.canControl&&b.status==='PENDING_APPROVAL'}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={s.version}/><input type="hidden" name="target" value={b.id}/><label>Approval / exception reason<input name="reason" required/></label><button name="action" value="approve-bill">Approve and post</button><button name="action" value="void-bill">Void unposted bill</button></form>{/if}</td></tr>{:else}<tr><td colspan="6">No bills in this view.</td></tr>{/each}</tbody></table></div><p>AP control difference: <strong>{money(r.apDifference)}</strong></p>
  </section>
  {#if w.canWrite}<section><h2>New vendor bill</h2><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><input type="hidden" name="action" value="bill"/><label>Vendor<select name="partyId" required><option value="">Choose vendor</option>{#each w.vendors as v}<option value={v.id}>{v.name||v.id}</option>{/each}</select></label><label>Bill number<input name="number" required/></label><label>Bill date<input name="date" type="date" value={today} required/></label><label>Due date<input name="dueDate" type="date" value={today} required/></label><label>Terms<input name="terms"/></label><label>Purchase order<select name="orderId"><option value="">No PO / simple AP</option>{#each w.orders as o}<option value={o.id}>{o.number}</option>{/each}</select></label>
   {#each Array(lineCount) as _,index}<fieldset class="wide bill-line"><legend>Line {index+1}</legend><div class="editor"><label>Description<input name="description" required/></label><label>Quantity<input name="quantity" type="number" min="0.01" step="0.01" value="1" required/></label><label>Unit cost<input name="unitCost" type="number" min="0" step="0.01" required/></label><label>Expense account<select name="lineAccount">{#each s.accounts.filter(a=>['EXPENSE','COST_OF_GOODS_SOLD'].includes(a.type)) as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label><label>Job<select name="lineJobId"><option value="">Company expense</option>{#each w.jobChoices as j}<option value={j.id}>{j.name}</option>{/each}</select></label><label>Category<select name="lineCategory">{#each categories as c}<option>{c}</option>{/each}</select></label><label>Cost code<select name="lineCostCode"><option value="">Uncoded</option>{#each s.costCodes as c}<option value={c.code}>{c.name}</option>{/each}</select></label><label>PO line<select name="orderLineId"><option value="">No linked line</option>{#each w.orders as o}{#each o.lines as l}<option value={l.id}>{o.number} · {l.description}</option>{/each}{/each}</select></label></div></fieldset>{/each}
   <button type="button" onclick={()=>lineCount=Math.min(100,lineCount+1)}>Add bill line</button><label>Tax<input name="tax" type="number" min="0" step="0.01" value="0"/></label><label>Shipping<input name="shipping" type="number" min="0" step="0.01" value="0"/></label><label class="wide">Notes<input name="reason"/></label><button class="primary">Submit for approval</button></form><p>Purchase tax and shipping post as unallocated direct cost. Allocate them to Jobs through explicit bill lines when required.</p></section>
   <section><h2>Record vendor payment or credit</h2><p>Record payment completed outside TurnKeyOps. This does not send funds.</p><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Transaction<select name="action"><option value="vendor-payment">Vendor payment</option><option value="vendor-credit">Vendor credit</option><option value="vendor-refund">Vendor payment refund</option></select></label><label>Vendor<select name="partyId">{#each w.vendors as v}<option value={v.id}>{v.name||v.id}</option>{/each}</select></label><label>Date<input name="date" type="date" value={today} required/></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required/></label><label>Cash account<select name="account">{#each s.cashAccounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>Method<input name="method" required/></label><label>Check / ACH / credit reference<input name="reference" required/></label><label>Unique transaction reference<input name="sourceKey" required/></label><label class="wide">Allocations (bill ID, amount — one per row)<textarea name="allocations" required rows="3"></textarea></label><label class="wide">Reason<input name="reason" required/></label><button class="primary">Record vendor transaction</button></form></section>{/if}
 {:else if view==='jobs'}
  <section><h2>Job health</h2>{#if w.canWrite}<form method="POST" action="?/save" use:enhance class="inline"><input type="hidden" name="version" value={s.version}/><label>Accepted Job<select name="jobId">{#each w.jobChoices as j}<option value={j.id}>{j.name}</option>{/each}</select></label><button name="action" value="seed-budget">Seed accepted Estimate budget</button></form>{/if}
   {#each w.jobs as j}<article><h3><a href={`${data.basePath}/jobs?job=${j.jobId}`}>{jobName(j.jobId)}</a></h3><dl class="job-metrics"><div><dt>Sold value</dt><dd>{money(j.contractValue)}</dd></div><div><dt>Budget</dt><dd>{Object.values(j.budget).some(v=>v===null)?'Incomplete':money(Object.values(j.budget).reduce<number>((sum,v)=>sum+(v||0),0))}</dd></div><div><dt>Committed</dt><dd>{money(j.committed)}</dd></div><div><dt>Actual</dt><dd>{money(j.actual)}</dd></div><div><dt>Recognized revenue</dt><dd>{money(j.revenue)}</dd></div><div><dt>Gross profit / margin</dt><dd>{j.costDataIncomplete?'Cost data incomplete':`${money(j.grossProfit)} / ${j.grossMargin?.toFixed(1)??'—'}%`}</dd></div></dl><p>{j.completenessNote}</p><details><summary>Category budget and actual</summary>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>{jobName(j.jobId)} cost categories</caption><thead><tr><th scope="col">Category</th><th scope="col">Budget</th><th scope="col">Actual</th></tr></thead><tbody>{#each Object.entries(j.budget) as [category,budget]}<tr><th scope="row">{category}</th><td>{money(budget)}</td><td>{money(j.categories.find(c=>c.category===category)?.amount||0)}</td></tr>{/each}</tbody></table></div></details>{#if w.canWrite}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={s.version}/><input type="hidden" name="jobId" value={j.jobId}/><button name="action" value="sync-job-changes">Refresh signed Job changes</button></form>{/if}{#if w.canControl}<details><summary>Review budget and cost completeness</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><input type="hidden" name="jobId" value={j.jobId}/>{#each categories as category}<label>{category} budget<input type="number" min="0" step="0.01" name={`budget.${category}`} value={j.budget[category]??''} placeholder="Unknown"/></label>{/each}<label class="wide">Review evidence<input name="reason" required/></label><label class="wide"><span><input type="checkbox" name="complete"/>I reviewed all incurred costs and confirm they are complete.</span></label><button name="action" value="budget-review">Record reviewed budget</button></form></details>{/if}</article>{:else}<p>No accepted Job budgets have been seeded.</p>{/each}
  </section>
  {#if w.canWrite}<section><h2>Record incurred labor or other direct cost</h2><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><input type="hidden" name="action" value="job-cost"/><label>Job<select name="jobId">{#each w.jobChoices as j}<option value={j.id}>{j.name}</option>{/each}</select></label><label>Category<select name="category">{#each categories.filter(c=>c!=='MATERIAL') as c}<option>{c}</option>{/each}</select></label><label>Date<input name="date" type="date" value={today} required/></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required/></label><label>Labor hours<input name="hours" type="number" min="0.01" step="0.01"/></label><label>Authorized hourly cost<input name="rate" type="number" min="0" step="0.01"/></label><label>Accrual / equity account<select name="account">{#each s.accounts.filter(a=>['LIABILITY','EQUITY'].includes(a.type)&&a.code!==s.policy.accounts.ap&&a.code!==s.policy.accounts.tax) as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label><label>Unique source reference<input name="sourceKey" required/></label><label class="wide">Reason / source evidence<input name="reason" required/></label><button class="primary">Record incurred cost</button></form><p>Material and vendor service costs originate from approved bills. Labor is an incurred cost interface, separate from payroll.</p></section>{/if}
 {:else if view==='cash'}
  <section><h2>Bank activity</h2><div class="summary">{#each r.cash as a}<div><h3>{a.name}</h3><strong>{money(a.balance)}</strong></div>{/each}</div>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>Imported statement activity</caption><thead><tr><th scope="col">Date</th><th scope="col">Reference</th><th scope="col" class="number">Amount</th><th scope="col">Review</th></tr></thead><tbody>{#each s.bankTransactions as b}<tr><th scope="row">{b.date}</th><td>{b.reference}<small>{b.externalId}</small></td><td class="number">{money(b.amount)}</td><td>{#if b.reconciliationId}Reconciled{:else if b.journalId}Matched — pending reconciliation{:else}<p>Unmatched</p>{#if w.canWrite}{#each w.suggestions.find(v=>v.id===b.id)?.candidates||[] as candidate}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={s.version}/><input type="hidden" name="target" value={b.id}/><input type="hidden" name="reference" value={candidate.id}/><input type="hidden" name="reason" value="Statement match reviewed and confirmed"/><p>{candidate.date} · {candidate.memo} · {candidate.confidence}</p><button name="action" value="bank-match">Confirm match</button></form>{/each}{/if}{/if}</td></tr>{:else}<tr><td colspan="4">No bank activity imported.</td></tr>{/each}</tbody></table></div></section>
  {#if w.canWrite}<section><h2>Import bank statement</h2><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Cash account<select name="account">{#each s.cashAccounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>Statement reference<input name="reference" required/></label><label class="wide">CSV rows: external ID, date (YYYY-MM-DD), signed amount, reference<textarea name="rows" required rows="4"></textarea></label><button name="action" value="bank-import" class="primary">Import for review</button></form></section>{/if}
  {#if w.canWrite}<details><summary>Add a bank or cash account</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Account reference<input name="cashId" required/></label><label>Account name<input name="name" required/></label><label>Ledger asset account<select name="account">{#each s.accounts.filter(a=>a.type==='ASSET') as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label><label>Institution<input name="institution"/></label><label>Masked account reference (last four digits only)<input name="maskedReference" maxlength="20"/></label><button name="action" value="cash-account">Add cash account</button></form></details>{/if}
  {#if w.canControl}<section><h2>Complete reconciliation</h2><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Cash account<select name="account">{#each s.cashAccounts as a}<option value={a.id}>{a.name}</option>{/each}</select></label><label>Statement reference<input name="reference" required/></label><label>Statement start<input name="date" type="date" required/></label><label>Statement end<input name="endDate" type="date" required/></label><label>Opening statement balance<input name="openingBalance" type="number" step="0.01" required/></label><label>Closing statement balance<input name="amount" type="number" step="0.01" required/></label><button name="action" value="reconcile" class="primary">Confirm reconciliation</button></form></section>{/if}
 {:else if view==='reports'}
  <section><h2>Financial statements</h2><p><a href={`${data.basePath}/finance/export?type=trial&from=${r.from}&asOf=${r.asOf}`}>Export trial balance</a> · <a href={`${data.basePath}/finance/export?type=income&from=${r.from}&asOf=${r.asOf}`}>Export income statement</a> · <a href={`${data.basePath}/finance/export?type=aging&from=${r.from}&asOf=${r.asOf}`}>Export AR / AP aging</a></p><p>{r.from} through {r.asOf} · USD · posted activity</p><dl class="job-metrics"><div><dt>Assets</dt><dd>{money(r.balanceSheet.assets)}</dd></div><div><dt>Liabilities</dt><dd>{money(r.balanceSheet.liabilities)}</dd></div><div><dt>Equity including earnings</dt><dd>{money(r.balanceSheet.equity)}</dd></div><div><dt>Balance sheet difference</dt><dd>{money(r.balanceSheet.difference)}</dd></div><div><dt>Period profit / loss</dt><dd>{money(r.profit)}</dd></div></dl>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>Income statement — credits less debits (expenses shown negative)</caption><thead><tr><th scope="col">Account</th><th scope="col">Type</th><th scope="col" class="number">Amount</th></tr></thead><tbody>{#each r.incomeStatement as a}<tr><th scope="row">{a.code} · {a.name}</th><td>{a.type}</td><td class="number">{money(a.amount)}</td></tr>{/each}</tbody></table></div>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>Trial balance as of {r.asOf}</caption><thead><tr><th scope="col">Account</th><th scope="col">Type</th><th scope="col" class="number">Debits</th><th scope="col" class="number">Credits</th><th scope="col" class="number">Net debit / (credit)</th></tr></thead><tbody>{#each r.trialBalance as a}<tr><th scope="row">{a.code} · {a.name}</th><td>{a.type}</td><td class="number">{money(a.debit)}</td><td class="number">{money(a.credit)}</td><td class="number">{money(a.balance)}</td></tr>{/each}</tbody></table></div><p>Trial balance difference: {money(r.trialDifference)} · AR difference: {money(r.arDifference)} · AP difference: {money(r.apDifference)}</p></section>
  <section><h2>AR / AP aging</h2>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Aging data table" tabindex="0"><table><caption>Open items as of {r.asOf}</caption><thead><tr><th scope="col">Ledger</th><th scope="col">Document</th><th scope="col">Due</th><th scope="col">Bucket</th><th scope="col" class="number">Balance</th></tr></thead><tbody>{#each r.aging as item}<tr><th scope="row">{item.kind}</th><td>{item.number}<small>{item.id}</small></td><td>{item.dueDate}</td><td>{item.bucket}</td><td class="number">{money(item.balance)}</td></tr>{:else}<tr><td colspan="5">No open items.</td></tr>{/each}</tbody></table></div></section>
 {:else if view==='ledger'}
  <section><h2>Chart of Accounts</h2>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>Tenant accounts</caption><thead><tr><th scope="col">Code</th><th scope="col">Name</th><th scope="col">Type</th><th scope="col">Normal balance</th><th scope="col">Control</th></tr></thead><tbody>{#each s.accounts as a}<tr><th scope="row">{a.code}</th><td>{a.name}</td><td>{a.type}</td><td>{a.normalBalance}</td><td>{a.systemControlled?'System':'Tenant'}</td></tr>{/each}</tbody></table></div></section>
  {#if w.canControl}<details><summary>Posting configuration</summary><p>Mappings are locked after the first posting. Revenue recognizes from posted invoices; material actuals come from approved vendor bills.</p><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/>{#each Object.entries(s.policy.accounts) as [role,code]}<label>{role} account<select name={`map.${role}`} value={code}>{#each s.accounts as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label>{/each}<label>PO / receipt matching<select name="matching" value={s.policy.matching}><option value="strict">Strict</option><option value="warning">Warning with review</option><option value="disabled">Simple AP</option></select></label><button name="action" value="policy">Save posting policy</button></form></details>{/if}
  <section><h2>Journal entries</h2><label>Account activity<select bind:value={accountFilter}><option value="">All accounts</option>{#each s.accounts as a}<option value={a.code}>{a.code} · {a.name}</option>{/each}</select></label>{#each s.journals.filter(j=>!accountFilter||j.lines.some(l=>l.account===accountFilter)).toReversed() as j}<details id={`journal-${j.id}`}><summary>{j.date} · {j.memo} · POSTED</summary><p>Source: {j.sourceType} · {j.sourceId} {#if j.reversesId}· Reverses {j.reversesId}{/if}</p><p>Posted by {j.postedBy} at {j.postedAtUtc}</p>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>{j.memo} journal lines</caption><thead><tr><th scope="col">Account</th><th scope="col" class="number">Debit</th><th scope="col" class="number">Credit</th><th scope="col">Job / cost code</th></tr></thead><tbody>{#each j.lines as l}<tr><th scope="row">{l.account}</th><td class="number">{money(l.debit)}</td><td class="number">{money(l.credit)}</td><td>{l.jobId?jobName(l.jobId):'—'} / {l.costCode||'—'}</td></tr>{/each}</tbody></table></div>{#if w.canControl&&['manual','job-cost'].includes(j.sourceType)}<form method="POST" action="?/save" use:enhance class="inline"><input type="hidden" name="version" value={s.version}/><input type="hidden" name="target" value={j.id}/><label>Correction date<input type="date" name="date" required/></label><label>Reason<input name="reason" required/></label><button name="action" value="reverse">Post compensating reversal</button></form>{/if}</details>{:else}<p>No posted journals.</p>{/each}
   {#each s.journalDrafts.filter(d=>!d.postedJournalId) as d}<article><h3>Draft: {d.memo}</h3><p>{d.date} · Debit {money(d.lines.reduce((a,l)=>a+l.debit,0))} · Credit {money(d.lines.reduce((a,l)=>a+l.credit,0))}</p>{#if w.canControl}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={s.version}/><input type="hidden" name="target" value={d.id}/><button name="action" value="post-draft">Approve and post draft</button></form>{/if}</article>{/each}
  </section>
  {#if w.canWrite}<section><h2>Draft a journal</h2><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Accounting date<input type="date" name="date" value={today} required/></label><label>Memo / source evidence<input name="reason" required/></label><label class="wide">Lines: account code, debit, credit, description (one CSV row per line)<textarea name="lines" rows="4" required placeholder="1000,100,0,Opening cash&#10;3000,0,100,Opening equity"></textarea></label><button name="action" value="draft-journal" class="primary">Save unposted draft</button></form></section>
   <details><summary>Account and cost-code setup</summary><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Account code<input name="code" required/></label><label>Account name<input name="name" required/></label><label>Type<select name="type">{#each ['ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE','COST_OF_GOODS_SOLD','OTHER_INCOME','OTHER_EXPENSE'] as type}<option>{type}</option>{/each}</select></label><label>Normal balance<select name="normalBalance"><option>DEBIT</option><option>CREDIT</option></select></label><button name="action" value="account">Add tenant account</button></form><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Cost code<input name="code" required/></label><label>Cost code name<input name="name" required/></label><label>Category<select name="category">{#each categories as c}<option>{c}</option>{/each}</select></label><label>Trade (optional)<input name="trade"/></label><button name="action" value="cost-code">Save cost code</button></form></details>{/if}
  {#if w.canControl}<details><summary>Opening balances and migration</summary><p>Import a balanced opening trial balance with reconciled AR/AP open items before the first posting. Preserve source external IDs.</p><form method="POST" action="?/save" use:enhance class="editor"><input type="hidden" name="version" value={s.version}/><label>Cutover date<input name="date" type="date" required/></label><label>Migration source reference<input name="sourceKey" required/></label><label>Source AR control<input name="arControl" type="number" step="0.01" required/></label><label>Source AP control<input name="apControl" type="number" step="0.01" required/></label><label class="wide">Opening trial balance: account code, debit, credit, description<textarea name="lines" required rows="4"></textarea></label><label class="wide">Open items: ID, AR/AP, party ID, number, date, due date, total, external source ID<textarea name="openItems" rows="4"></textarea></label><label class="wide">Validation / source reconciliation evidence<input name="reason" required/></label><button name="action" value="opening-import">Validate and import opening balances</button></form></details>{/if}
 {:else if view==='close'}
  <section><h2>Accounting periods</h2>{#if w.canControl}<form method="POST" action="?/save" use:enhance class="inline"><input type="hidden" name="version" value={s.version}/><label>Calendar month<input type="month" name="month" required/></label><button name="action" value="period">Open accounting month</button></form>{/if}
   {#each s.periods as p}<article><h3>{p.id} · {p.status}</h3><ul>{#each w.close.find(c=>c.id===p.id)?.issues||[] as issue}<li>{issue}</li>{:else}<li>Recorded subledgers and imported bank activity pass close checks.</li>{/each}</ul>{#if w.canControl}<form method="POST" action="?/save" use:enhance class="inline"><input type="hidden" name="version" value={s.version}/><input type="hidden" name="target" value={p.id}/><label>Close / reopening reason<input name="reason" required/></label><button name="action" value={p.status==='OPEN'?'close':'reopen'}>{p.status==='OPEN'?'Close reviewed period':'Authorize reopening'}</button></form>{/if}</article>{:else}<p>Create an accounting month before posting transactions.</p>{/each}
  </section>
  <section><h2>Financial audit trail</h2>
<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) -->
<div class="table-scroll" role="region" aria-label="Financial data table" tabindex="0"><table><caption>Recorded financial actions</caption><thead><tr><th scope="col">When</th><th scope="col">Action</th><th scope="col">Actor</th><th scope="col">Reason / source</th></tr></thead><tbody>{#each s.audit.toReversed() as a}<tr><th scope="row">{a.atUtc}</th><td>{a.action}</td><td>{a.actor}</td><td>{a.reason||a.target||'—'}</td></tr>{:else}<tr><td colspan="4">No financial activity yet.</td></tr>{/each}</tbody></table></div></section>
 {/if}
</div>
<style>
 .finance{--text-primary:var(--text-strong,#182a2c);--text-secondary:var(--text-muted,#53666a);--border-color:var(--border,#d4dcdd);--surface-hover:var(--surface-subtle,#eef5f4);color:var(--text-primary);padding:1.25rem;max-width:1500px;margin:auto}header,.section-heading{display:flex;justify-content:space-between;gap:1rem;align-items:start;flex-wrap:wrap}.eyebrow{color:var(--teal-text,#0f766e);font-weight:700;letter-spacing:.08em;font-size:.75rem}h1{font-size:1.8rem;letter-spacing:-.04em;margin:.25rem 0}h2{font-size:1.05rem;font-weight:650;margin:0 0 1rem}h3{font-size:1rem;font-weight:600;margin:.5rem 0}p{font-size:.875rem;line-height:1.55;margin:.5rem 0}nav{display:flex;gap:.25rem;flex-wrap:wrap;margin:1.5rem 0;border-bottom:1px solid var(--border-color,#d4dcdd);padding-bottom:.75rem}button{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;min-height:40px;border:1px solid var(--border-color,#c5d0d1);background:var(--surface,#fff);color:inherit;border-radius:.4rem;padding:.5rem .75rem;font-size:.85rem;font-weight:550;cursor:pointer}button:hover{background:var(--surface-hover,#eef5f4)}button[aria-current],button[aria-pressed=true]{background:var(--teal-soft,#e2f2ef);border-color:var(--teal-text,#0f766e);color:var(--teal-text,#115e59)}.primary{background:var(--cta,#c2410c);color:var(--cta-text,#fff);border-color:var(--cta,#c2410c)}.primary:hover{background:var(--cta-hover,#9a3412)}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible,a:focus-visible{outline:3px solid #0d9488;outline-offset:3px}section{padding:1.4rem 0;border-bottom:1px solid var(--border-color,#d4dcdd)}.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1.25rem}.summary strong{font-size:1.7rem;letter-spacing:-.03em}.summary section{padding:1rem 0}.summary h2,.summary h3{font-size:.85rem;color:var(--text-secondary,#53666a)}.summary p,.muted{color:var(--text-secondary,#53666a)}.feedback{padding:.75rem;background:var(--teal-soft,#e2f2ef);color:var(--teal-text,#115e59);border-left:3px solid #0f766e}.feedback.problem{background:var(--warning-soft,#fff1e8);color:var(--warning-text,#9a3412);border-color:#c2410c}.priorities{padding:0;list-style:none}.priorities button{width:100%;justify-content:space-between;border:none;border-radius:0;padding:.8rem 0;border-bottom:1px solid var(--border-color,#d4dcdd);text-align:left}.priorities span{color:var(--teal-text,#0f766e)}.report-dates,.inline{display:flex;gap:.75rem;align-items:end;flex-wrap:wrap}.editor{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.8rem;align-items:end}.editor .wide{grid-column:1/-1}label{display:grid;gap:.35rem;font-size:.8rem;font-weight:550;min-width:0}input[type=checkbox]{width:20px;min-height:20px;vertical-align:middle;margin-right:.5rem}input,select,textarea{min-height:40px;max-width:100%;width:100%;border:1px solid var(--border-color,#b8c8ca);border-radius:.35rem;padding:.5rem;background:var(--surface,#fff);color:inherit;font:inherit}textarea{font-family:ui-monospace,monospace;font-weight:400}.table-scroll{overflow-x:auto;max-width:100%;margin:.75rem 0}table{width:100%;border-collapse:collapse;font-size:.8rem}caption{text-align:left;color:var(--text-secondary,#53666a);padding:.5rem 0}th,td{text-align:left;padding:.65rem .6rem;border-bottom:1px solid var(--border-color,#d4dcdd);vertical-align:top}thead th{font-weight:650;background:var(--surface-hover,#f4f7f7)}th small,td small{display:block;font-size:.65rem;font-weight:400;overflow-wrap:anywhere;color:var(--text-secondary,#53666a)}.number{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.filters{display:flex;gap:.35rem;flex-wrap:wrap;margin-bottom:1rem}.exception{color:var(--warning-text,#9a3412)}a{color:var(--teal-text,#0f766e);text-decoration:underline;text-underline-offset:3px}article{padding:1rem 0;border-bottom:1px solid var(--border-color,#d4dcdd)}.job-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin:1rem 0}.job-metrics dt{font-size:.8rem;color:var(--text-secondary,#53666a)}.job-metrics dd{margin:.3rem 0;font-size:1.1rem;font-weight:600}details{border-bottom:1px solid var(--border-color,#d4dcdd);padding:.9rem 0}summary{cursor:pointer;font-weight:600;min-height:32px}.bill-line{border:0;border-top:1px solid var(--border-color,#d4dcdd);padding:.75rem 0}.bill-line legend{font-size:.8rem;padding-right:.75rem}ul{padding-left:1.1rem;font-size:.85rem}

 @media(max-width:800px){.finance{padding:1rem}.summary{grid-template-columns:repeat(2,minmax(0,1fr))}.editor{grid-template-columns:repeat(2,minmax(0,1fr))}.job-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.priorities button{display:grid;gap:.5rem}.report-dates{width:100%}.report-dates label{flex:1}.summary strong{font-size:1.35rem}}
 @media(max-width:480px){.editor{grid-template-columns:1fr}.finance h1{font-size:1.5rem}.summary{gap:1rem}nav button{font-size:.75rem;padding:.4rem .5rem}}
</style>
